await Actor.init();
try {
  const inputBytes = await readFile("./input-manifest.json");
  const manifest = JSON.parse(inputBytes.toString("utf8"));
  const inputFileSha256 = hash(inputBytes);
  const rowArraySha256 = hash(JSON.stringify(manifest.rows));
  if (manifest.rows.length !== 100 || manifest.rowsSha256 !== rowArraySha256) {
    throw new Error("Frozen input row count or embedded row hash mismatch");
  }
  await execFileAsync(process.execPath, ["probe.mjs"], { timeout: 840000, maxBuffer: 1048576, windowsHide: true });
  const results = JSON.parse(await readFile("./local-results.json", "utf8"));
  const resultIds = results.rows.map((row) => row.rowId);
  const inputIds = manifest.rows.map((row) => row.rowId);
  if (results.rows.length !== 100 || new Set(resultIds).size !== 100 ||
      inputIds.some((id) => !resultIds.includes(id)) ||
      results.rows.some((row) => !inputIds.includes(row.rowId))) {
    throw new Error("Hosted evidence does not cover frozen row IDs exactly once");
  }
  const hostedEvidence = {
    ...results,
    evidenceType: "issue18_hosted_node20_http_identity_probe",
    hosted: {
      actorStartedAtUtc: startedAtUtc,
      actorCompletedAtUtc: new Date().toISOString(),
      nodeVersion: process.version,
      platform: process.platform,
      architecture: process.arch,
      frozenInputFileSha256: inputFileSha256,
      frozenRowArraySha256: rowArraySha256,
      rowIdsExactOnce: true,
    },
  };
  await writeFile("./hosted-results.json", JSON.stringify(hostedEvidence, null, 2) + "\n");
  const { rows, ...summary } = hostedEvidence;
  await Actor.pushData({ ...summary, recordType: "summary" });
  for (const row of rows) await Actor.pushData({ ...row, recordType: "row" });
  console.log("ISSUE18_HOSTED_PROBE " + JSON.stringify({
    nodeVersion: process.version,
    platform: process.platform,
    architecture: process.arch,
    frozenInputFileSha256: inputFileSha256,
    frozenRowArraySha256: rowArraySha256,
    totalRows: results.totalRows,
    candidateCounts: results.candidateCounts,
    accessCounts: results.accessCounts,
    identityCounts: results.identityCounts,
    articleLikeCount: results.articleLikeCount,
    strictConfirmedSuccesses: results.strictConfirmedSuccesses,
    retryCount: results.retryCount,
    perCell: results.perCell,
    startedAtUtc: results.startedAtUtc,
    completedAtUtc: results.completedAtUtc,
  }));
} finally {
  await Actor.exit();
}

